patterns.codeAfter:
button:focus {
  outline: 2px solid #005fcc;
  outline-offset: 2px;
}

/* For mouse users who don't need it */
button:focus:not(:focus-visible) {
  outline: none;
}

button:focus-visible {
  outline: 2px solid #005fcc;
  outline-offset: 2px;
}

patterns.codeBefore:
/* Light gray on white - ratio ~2:1 */
.text {
  color: #999999;
  background: #ffffff;
}

patterns.codeAfter:
/* Dark gray on white - ratio ~7:1 */
.text {
  color: #595959;
  background: #ffffff;
}
